     1→import type { NextRequest} from "next/server";
     2→import { NextResponse } from "next/server";
     3→import { headers } from "next/headers";
     4→import { auth } from "@/lib/auth";
     5→import { FavoriteEnrichmentService } from "@/lib/services/favorites/enrichment";
     6→
     7→export async function POST(request: NextRequest) {
     8→  try {
     9→    const session = await auth.api.getSession({
    10→      headers: await headers(),
    11→    });
    12→    if (!session?.user?.id) {
    13→      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    14→    }
    15→
    16→    const { action, favoriteId, userId } = await request.json();
    17→
    18→    const enrichmentService = new FavoriteEnrichmentService();
    19→
    20→    switch (action) {
    21→      case "enrich-favorite":
    22→        if (!favoriteId) {
    23→          return NextResponse.json({ error: "favoriteId is required" }, { status: 400 });
    24→        }
    25→
    26→        // Vérifier que le favori appartient à l'utilisateur
    27→        const { PrismaClient } = await import("@/generated/prisma");
    28→        const prisma = new PrismaClient();
    29→        const favorite = await prisma.favorite.findFirst({
    30→          where: {
    31→            id: favoriteId,
    32→            userId: session.user.id,
    33→          },
    34→        });
    35→
    36→        if (!favorite) {
    37→          return NextResponse.json({ error: "Favorite not found or access denied" }, { status: 404 });
    38→        }
    39→
    40→        const result = await enrichmentService.enrichFavoriteWithDPE(favoriteId);
    41→        return NextResponse.json(result);
    42→
    43→      case "enrich-user-favorites":
    44→        const targetUserId = userId || session.user.id;
    45→        
    46→        // Vérifier les permissions
    47→        if (targetUserId !== session.user.id && session.user.role !== "admin") {
    48→          return NextResponse.json({ error: "Unauthorized to enrich other user's favorites" }, { status: 403 });
    49→        }
    50→
    51→        const userResults = await enrichmentService.enrichUserFavorites(targetUserId);
    52→        return NextResponse.json({
    53→          success: true,
    54→          results: userResults,
    55→          total: userResults.length,
    56→          successful: userResults.filter(r => r.success).length,
    57→          failed: userResults.filter(r => !r.success).length,
    58→        });
    59→
    60→      case "enrich-all-without-dpe":
    61→        // Admin seulement
    62→        if (session.user.role !== "admin") {
    63→          return NextResponse.json({ error: "Unauthorized" }, { status: 403 });
    64→        }
    65→
    66→        const allResults = await enrichmentService.enrichAllFavoritesWithoutDPE();
    67→        return NextResponse.json({
    68→          success: true,
    69→          results: allResults,
    70→          total: allResults.length,
    71→          successful: allResults.filter(r => r.success).length,
    72→          failed: allResults.filter(r => !r.success).length,
    73→        });
    74→
    75→      default:
    76→        return NextResponse.json({ error: "Invalid action" }, { status: 400 });
    77→    }
    78→  } catch (error) {
    79→    console.error("Error in DPE enrichment API:", error);
    80→    return NextResponse.json(
    81→      { error: "Internal server error" },
    82→      { status: 500 }
    83→    );
    84→  }
    85→}

