   309→  private async makeRequest(endpoint: string, params?: string): Promise<any> {
   310→    const url = `${this.baseUrl}${endpoint}${params ? `?${params}` : ''}`;
   311→    
   312→    const headers: Record<string, string> = {
   313→      "Content-Type": "application/json",
   314→      "Accept": "application/json",
   315→    };
   316→    
   317→    if (this.apiKey) {
   318→      headers.Authorization = `Bearer ${this.apiKey}`;
   319→    }
   320→    
   321→    const controller = new AbortController();
   322→    const timeoutId = setTimeout(() => controller.abort(), this.timeout);
   323→    
   324→    try {
   325→      let response: Response;
   326→      let attempt = 0;
   327→      
   328→      do {
   329→        attempt++;
   330→        response = await fetch(url, {
   331→          method: "GET",
   332→          headers,
   333→          signal: controller.signal,
   334→        });
   335→        
   336→        if (response.ok || attempt >= this.maxRetries) {
   337→          break;
   338→        }
   339→        
