/**
 * Normalise les données DPE brutes provenant de différentes sources
 */
export function normalizeDPERawData(rawData: Record<string, unknown> | unknown): Partial<DPE> {
  const data = rawData as Record<string, unknown>;
  return {
    id: (data.id ?? data.numero_dpe ?? `dpe_${Date.now()}`) as string,
    address: (data.address ?? data.adresse) as string,
    postalCode: (data.postalCode ?? data.code_postal) as string,
    city: (data.city ?? data.ville) as string,
    coordinates: (data.coordinates ?? data.coordonnees_geographiques) as [number, number] | undefined,

    propertyType: (data.propertyType ?? data.type_batiment ?? "apartment") as "apartment" | "house" | "mixed_use" | "other",
    surface: (data.surface ?? data.surface_habitable) as number,
    yearBuilt: (data.yearBuilt ?? data.annee_construction) as number,
    livingArea: (data.livingArea ?? data.surface_habitable) as number | undefined,

    energyConsumption: (data.energyConsumption ?? data.consommation_energie ?? {
      value: (data.consommation_energie_value ?? data.consomme_energie ?? 0) as number,
      unit: "kWh_ep/m².an" as const,
      maxAuthorized: (data.maxAuthorized ?? 450) as number,
      class: (data.classe_consommation_energie ?? data.classe_energy ?? "G") as EnergyClass,
    }) as { value: number; unit: "kWh_ep/m².an"; maxAuthorized: number; class: EnergyClass },

    gesEmission: (data.gesEmission ?? data.emission_ges ?? {
      value: (data.emission_ges_value ?? data.estimation_ges ?? 0) as number,
      unit: "kgCO2/m².an" as const,
      maxAuthorized: (data.maxAuthorizedGes ?? 80) as number,
      class: (data.classe_estimation_ges ?? data.classe_ges ?? "G") as GesClass,
    }) as { value: number; unit: "kgCO2/m².an"; maxAuthorized: number; class: GesClass },

    mainEnergyType: (data.mainEnergyType ?? data.type_energie_principale ?? "electricity") as "electricity" | "gas" | "fuel_oil" | "wood" | "coal" | "network" | "other",

    dpeDate: (data.dpeDate ?? data.date_dpe) as string,
    dpeValidity: (data.dpeValidity ?? data.date_validite_dpe) as string,
    dataSource: (data.dataSource ?? "unknown") as string,
    lastUpdated: new Date().toISOString(),
  };
}

